/**
 * Runtime probe for the browser-side Supabase configuration.
 *
 * `src/integrations/supabase/client.ts` is generated by Lovable and throws as
 * soon as any property is read while `VITE_SUPABASE_URL` /
 * `VITE_SUPABASE_PUBLISHABLE_KEY` are missing from the build. That is the right
 * verdict for the dashboard, but it must not take the public catalogue down
 * with it: a build deployed without the values inlined used to white-screen
 * every page from the root route's auth subscription alone.
 *
 * Server-side counterpart of this idea: `getManagedContent` returns empty lists
 * instead of throwing when `SUPABASE_URL` / `SUPABASE_PUBLISHABLE_KEY` are
 * absent, so the static catalogue still renders.
 *
 * Read the same keys as the generated client: `import.meta.env` for the browser
 * bundle (Vite inlines them at build time) and `process.env` for SSR runtimes.
 */

type EnvSource = Record<string, string | undefined>;

function browserEnv(): EnvSource {
  return import.meta.env as EnvSource;
}

function serverEnv(): EnvSource | undefined {
  return typeof process === "undefined" ? undefined : (process.env as EnvSource);
}

function firstPresent(clientKey: string, serverKey: string): string | undefined {
  const fromBuild = browserEnv()[clientKey];
  if (fromBuild) return fromBuild;
  return serverEnv()?.[serverKey];
}

/** Publishable URL the browser should talk to, if this build knows it. */
export function supabaseUrl(): string | undefined {
  return firstPresent("VITE_SUPABASE_URL", "SUPABASE_URL");
}

/** Publishable (anon-safe) key, if this build knows it. Never a secret key. */
export function supabasePublishableKey(): string | undefined {
  return firstPresent("VITE_SUPABASE_PUBLISHABLE_KEY", "SUPABASE_PUBLISHABLE_KEY");
}

/**
 * False means: touching `supabase` from the client will throw. Callers that only
 * need auth keep working, they just say so instead of crashing the page.
 */
export function isSupabaseConfigured(): boolean {
  return Boolean(supabaseUrl() && supabasePublishableKey());
}

/** Require both Supabase URL and publishable key; throw if missing. */
export interface SupabaseConfig {
  url: string;
  publishableKey: string;
}

export function requireSupabaseEnv(): SupabaseConfig {
  const url = supabaseUrl();
  const publishableKey = supabasePublishableKey();

  if (!url || !publishableKey) {
    const missing = [
      ...(!url ? ["SUPABASE_URL"] : []),
      ...(!publishableKey ? ["SUPABASE_PUBLISHABLE_KEY"] : []),
    ];
    const message = `Missing Supabase environment variable(s): ${missing.join(", ")}. Connect Supabase in Lovable Cloud.`;
    console.error(`[Supabase] ${message}`);
    throw new Error(message);
  }

  return { url, publishableKey };
}
